pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining free space after placement
    let mut score = post_residual as f64;

    // ----- Dead‑space penalty (focus on the gap to the next item) -----
    if post_residual > 0 && post_residual < next_item_size {
        let missing = next_item_size - post_residual;
        let gap_ratio = missing as f64 / bin_capacity as f64;
        score += missing as f64 * (1.0 + gap_ratio) * 0.5;
    }

    // ----- Residual proportion penalty -----
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio.powi(2) * 0.3;

    // ----- Bin fullness preference -----
    let fullness = 1.0 - residual_ratio; // 0..1
    score -= fullness.powi(2) * 0.4;

    // ----- Open‑bin pressure -----
    let bin_pressure = (open_bins_count as f64).powf(1.1) * 0.12;
    score += bin_pressure;

    // ----- Unique fitting bin bonus -----
    if fitting_bins_count == 1 {
        score -= 1000.0;
    }

    // ----- New‑bin cost adjustment -----
    if bin_residual == bin_capacity {
        // More expensive when many bins are open or average fill is low
        let base_penalty = 90.0 + (open_bins_count as f64) * 2.0;
        let mean_adj = if mean_residual > 0.05 * bin_capacity as f64 {
            -mean_residual * 6.0
        } else {
            0.0
        };
        score += base_penalty + mean_adj;
    }

    // ----- Mean residual adjustment -----
    if mean_residual > 0.1 * bin_capacity as f64 {
        score += mean_residual * 0.12;
    }

    // ----- Progress‑based tightening -----
    let progress = step_index as f64 / total_items as f64;
    score += progress * 0.08;

    // ----- Item size coupling -----
    if item_size as f64 > 0.7 * bin_capacity as f64 {
        let large_factor = (item_size as f64 / bin_capacity as f64).powi(2);
        score += large_factor * 0.6;
    }

    // ----- Next‑item fit bonus -----
    if next_item_size <= post_residual {
        score -= 60.0; // Prefer bins that can still hold the next item
    }

    // ----- Small residual reward -----
    if residual_ratio < 0.05 {
        score -= 5.0; // Almost full bins are highly desirable
    }

    // ----- Excess free space penalty -----
    if bin_residual > item_size {
        let leftover = bin_residual - item_size;
        if leftover as f64 > 0.2 * bin_capacity as f64 {
            score += leftover as f64 * 0.02;
        }
    }

    score
}

