pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // Dead‑space penalty or reward based on the next item
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 120.0;
        } else {
            score -= 6.0;
        }
    }

    // Mean residual coupling: penalise over‑filling relative to average
    let mean_diff = post_residual as f64 - mean_residual;
    if mean_diff > 0.0 {
        score += mean_diff * 0.45;
    } else {
        score += mean_diff * 0.20;
    }

    // Residual ratio penalty (scaled down)
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 3.5;

    // Time‑dependent weighting – early in the stream penalise more
    let progress = step_index as f64 / total_items as f64;
    let time_weight = 1.0 - progress;
    score += time_weight * (post_residual as f64 * 0.05);

    // Encourage use of existing bins when many are open
    if open_bins_count > 0 {
        score -= (open_bins_count as f64) * 0.12;
    }

    // Reward a perfect fit when it is the only viable bin
    if fitting_bins_count == 1 && bin_residual == item_size {
        score -= 10.0;
    }

    // Reward close fits (within 3 units)
    if (bin_residual as i32 - item_size as i32).abs() <= 3 {
        score -= 3.0;
    }

    // Reward very tight bins (<7% of capacity)
    if residual_ratio < 0.07 {
        score -= 2.5;
    }

    // Extra penalty when many bins are open and residual is high
    if open_bins_count > 4 && post_residual > (mean_residual * 1.15) as u32 {
        score += 8.0;
    }

    // Penalise bins that are not tightly packed
    if fitting_bins_count > 2 {
        score += 4.0;
    }

    // Lookahead: assess next item fit in this bin and in a new bin
    let next_fit_in_bin = next_item_size <= bin_residual;
    let next_fit_in_new = next_item_size <= bin_capacity;
    if next_fit_in_bin {
        score -= 6.0;
    } else if !next_fit_in_new {
        score += 10.0;
    } else {
        score += 2.0;
    }

    // Last‑item reward – any bin is acceptable
    if step_index + 1 == total_items {
        score -= 5.0;
    }

    // Squared residual ratio penalty for very loose bins
    if residual_ratio.powi(2) > 0.5 {
        score += 3.0;
    }

    // New‑bin candidate penalty – open a new bin only if justified
    if bin_residual == bin_capacity {
        score += 1.0;
    }

    // Large open‑bin count penalty
    if open_bins_count > 10 {
        score += 5.0;
    }

    // Next item size relative to capacity
    let next_ratio = next_item_size as f64 / bin_capacity as f64;
    if next_ratio > 0.9 {
        score += 5.0;
    }

    // Early‑stream fitting‑count penalty
    if step_index < total_items / 3 && fitting_bins_count > 1 {
        score += 2.0;
    }

    // Small residual relative to mean gives slight reward
    if post_residual < (mean_residual * 0.8) as u32 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts at zero – we add penalties and rewards incrementally
    let mut score = 0.0_f64;

    // ------------------------------------------------------------------
    // 1. Residual proportion penalty – cubic to penalise medium gaps
    // ------------------------------------------------------------------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio.powi(3) * 0.30;

    // Small residual reward
    if residual_ratio < 0.02 {
        score -= 6.0;
    } else if residual_ratio < 0.05 {
        score -= 3.0;
    } else if residual_ratio < 0.15 {
        score += 1.5;
    }

    // ------------------------------------------------------------------
    // 2. Dead‑space penalty – missing next item after this placement
    // ------------------------------------------------------------------
    if post_residual < next_item_size {
        let missing = next_item_size - post_residual;
        score += missing as f64 * 0.5 * (1.0 + missing as f64 / bin_capacity as f64);
    }

    // ------------------------------------------------------------------
    // 3. Next‑item fit bonus/penalty – encourage bins that still fit the next item
    // ------------------------------------------------------------------
    if next_item_size <= post_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // ------------------------------------------------------------------
    // 4. Open‑bin pressure – mild penalty growing with sqrt(open_bins)
    // ------------------------------------------------------------------
    score += (open_bins_count as f64).sqrt() * 0.08;

    // ------------------------------------------------------------------
    // 5. Fitting‑bins count – huge bonus for the only candidate, small penalty for many
    // ------------------------------------------------------------------
    if fitting_bins_count == 1 {
        score -= 900.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.04;
    }

    // ------------------------------------------------------------------
    // 6. Item size coupling – prefer residual close to item size
    // ------------------------------------------------------------------
    let diff = (post_residual as i32 - item_size as i32).abs() as f64;
    score += diff * 0.02;

    // ------------------------------------------------------------------
    // 7. Large item handling – penalise poor fits for big items
    // ------------------------------------------------------------------
    if item_size as f64 > 0.80 * bin_capacity as f64 {
        if post_residual < item_size {
            score += 5.0;
        } else {
            score -= 2.0;
        }
    }

    // ------------------------------------------------------------------
    // 8. New‑bin cost – only when calling with an empty bin
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity {
        let base = 60.0 + (open_bins_count as f64) * 1.20;
        let mean_adj = if mean_residual > 0.07 * bin_capacity as f64 {
            -mean_residual * 3.0
        } else {
            0.0
        };
        score += base + mean_adj;
    }

    // ------------------------------------------------------------------
    // 9. Mean residual adjustment – penalise overall inefficiency
    // ------------------------------------------------------------------
    if mean_residual > 0.10 * bin_capacity as f64 {
        score += mean_residual * 0.08;
    }

    // ------------------------------------------------------------------
    // 10. Progress‑based tightening – tighter packing as we advance
    // ------------------------------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += progress.powf(1.10) * 0.04;

    // ------------------------------------------------------------------
    // 11. Excess free space penalty – discourage large leftovers
    // ------------------------------------------------------------------
    if bin_residual > item_size {
        let leftover = bin_residual - item_size;
        if leftover as f64 > 0.20 * bin_capacity as f64 {
            score += leftover as f64 * 0.02;
        }
    }

    score
}
